import './seriesbio.css';
import './seriesbio-overrides.css';
import { LiquidArtwork } from './components/LiquidArtwork';

type Role = 'Founder' | 'Investor';
type View = 'dashboard' | 'discover' | 'matches' | 'conversation' | 'dealroom' | 'profile' | 'pipeline';
type DemoProfile = {
  name: string; kind: 'fund' | 'startup'; mark: string; specialty: string; stage: string;
  location: string; ticket: string; score: number; reason: string; color: string;
  interested: boolean; description: string; metrics: string[];
};
type Meeting = { date: string; time: string; format: string; note: string; status: 'Pending' | 'Confirmed' | 'Declined' };
type ChatMessage = { from: Role; text: string; time: string };
type DemoState = {
  role: Role; view: View; entered: boolean; activeMatch: string; status: string; messages: ChatMessage[];
  meeting: Meeting | null; tasks: boolean[]; sentIntro: boolean; liked: string[]; passed: string[];
  founderName: string; profileSaved: boolean;
};

