function loadState(): DemoState {
  try { const saved = localStorage.getItem(KEY); return saved ? { ...initialState, ...JSON.parse(saved) } : initialState; }
  catch { return initialState; }
}
function Icon({ name }: { name: string }) {
  const paths: Record<string, string> = {
    grid: 'M4 4h6v6H4z M14 4h6v6h-6z M4 14h6v6H4z M14 14h6v6h-6z',
    discover: 'M12 3l2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4z',
    heart: 'M20.8 8.7c0 5.2-8.8 10.3-8.8 10.3S3.2 13.9 3.2 8.7A4.7 4.7 0 0 1 12 6.1a4.7 4.7 0 0 1 8.8 2.6Z',
    chat: 'M20 11.5a7.5 7.5 0 0 1-8 7.5 8.7 8.7 0 0 1-4-.9L4 20l1.3-3.4A7.2 7.2 0 0 1 4 12c0-4.1 3.6-7.5 8-7.5s8 3.1 8 7Z',
    layers: 'M12 3 3 8l9 5 9-5-9-5Zm-9 9 9 5 9-5M3 16l9 5 9-5',
    user: 'M20 21a8 8 0 0 0-16 0 M12 13a5 5 0 1 0 0-10 5 5 0 0 0 0 10Z',
    arrow: 'M5 12h14 M13 6l6 6-6 6',
    plus: 'M12 5v14 M5 12h14',
    chevron: 'm9 18 6-6-6-6',
    calendar: 'M7 3v4m10-4v4M4 9h16M5 5h14a1 1 0 0 1 1 1v13H4V6a1 1 0 0 1 1-1Z',
    close: 'M6 6l12 12M18 6 6 18',
    info: 'M12 11v6m0-10h.01M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0Z',
  };
  return <svg className="icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d={paths[name] || paths.arrow} /></svg>;
}
function Brand({ light = false }: { light?: boolean }) {
  return <div className={`brand ${light ? 'brand-light' : ''}`}><span className="brand-mark"><svg viewBox="0 0 34 34" aria-hidden="true"><path d="M24.9 3.5c-8.7.1-15.8 4.4-15.8 10.2 0 4.3 4.4 6.4 8.7 8.3 3.6 1.6 6.8 3.1 6.8 5.7 0 2.4-2.8 3.9-7.2 3.9-3.1 0-6.2-.9-9-2.3l2.5-5.5c1.9 1 4.1 1.8 6.1 1.8 1.4 0 2.2-.4 2.2-1 0-.8-2.1-1.7-4.4-2.8C10.6 19.5 5 16.7 5 11.4 5 4.8 12.6.2 25.1.2l-.2 3.3Z" fill="currentColor"/><path d="M10 29.7c3.2 1.3 6.2 1.9 9.5 1.9 6 0 9.5-2.6 9.5-6.3 0-4.1-4.1-6-8.7-8-3.6-1.5-6.9-2.9-6.9-5.4 0-2.1 2.4-3.8 6.6-4.4l.8 5.4c-1.4.3-2.1.7-2.1 1.2 0 .6 2.2 1.5 4.5 2.5 4.4 1.9 10.3 4.4 10.3 10.2 0 6.6-5.6 10.7-14.6 10.7-4.1 0-7.9-.7-11.6-2.2l2.7-5.6Z" fill="currentColor" opacity=".55" transform="translate(-2 -1)"/></svg></span><span className="brand-name">Series<span>Bio</span></span></div>;
}
function Pill({ children, tone = '' }: { children: React.ReactNode; tone?: string }) { return <span className={`pill ${tone}`}>{children}</span>; }
function MatchScore({ score }: { score: number }) { return <div className="match-score"><span className="score-ring"><b>{score}</b></span><span><b>Estimated fit</b><small>Illustrative compatibility</small></span></div>; }

function HeroStory({ onExplore }: { onExplore: () => void }) {
  return <div className="hero-art hero-glass-story" aria-label="Anteprima del matching SeriesBio">
    <div className="hero-art-copy"><span className="caption-kicker">IDEAS MEET CAPITAL</span><b>Readiness in.<br/>Matches out.</b><p>La ricerca incontra i partner giusti, un passo alla volta.</p></div>
    <div className="hero-floating-card"><span className="hero-card-icon">↔</span><span><small>Potenziale allineamento</small><b>Founder × Investor</b></span><span className="float-check">✓</span></div>
    <button className="hero-art-cta" onClick={onExplore}>Prova il matching <Icon name="arrow"/></button>
  </div>;
}

